    order_number varchar(50) NOT NULL, product_id integer NOT NULL, planned_quantity numeric(18,4) NOT NULL,
    completed_quantity numeric(18,4) NOT NULL DEFAULT 0, status varchar(30) NOT NULL DEFAULT 'PLANNED',
    UNIQUE(company_id, order_number)
);
CREATE TABLE IF NOT EXISTS mfg.quality_results (
    quality_result_id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(company_id),
    work_order_id uuid REFERENCES mfg.work_orders(work_order_id), test_code varchar(50) NOT NULL,
    result varchar(30) NOT NULL, measured_value numeric(19,6), recorded_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS ai.models (
    model_id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(company_id),
    model_code varchar(100) NOT NULL, version varchar(30) NOT NULL, status varchar(30) NOT NULL DEFAULT 'ACTIVE',
    UNIQUE(company_id, model_code, version)
);
CREATE TABLE IF NOT EXISTS ai.predictions (
    prediction_id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(company_id),
    model_id uuid REFERENCES ai.models(model_id), entity_type varchar(50) NOT NULL,
    entity_id varchar(100) NOT NULL, score numeric(19,8), created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS audit.events (
    event_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id uuid REFERENCES companies(company_id),
    actor_id varchar(100) NOT NULL, action varchar(50) NOT NULL, entity_type varchar(100) NOT NULL,
    entity_id varchar(100), details jsonb, occurred_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS mst.licenses (
    license_id uuid PRIMARY KEY, company_id uuid REFERENCES companies(company_id),
    license_key varchar(250) NOT NULL UNIQUE, status varchar(30) NOT NULL DEFAULT 'ACTIVE',
    expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now()
);
-- @shoutech-migration 005_roles.sql 57AFB05246C2839387DA4F1FB16F5FFE1BD17B9EC9FBE335F456AD1FFE34D56A 694D13A01463446E4C44B820614AC212C3951FED7D9620F4C93D38FF62E9F219 694D13A01463446E4C44B820614AC212C3951FED7D9620F4C93D38FF62E9F219 694D13A01463446E4C44B820614AC212C3951FED7D9620F4C93D38FF62E9F219
-- Enterprise role model: Administrator, User, Viewer only.
-- Existing Manager/Accountant assignments are normalized to User before the legacy roles are removed.

INSERT INTO roles (company_id, role_code, role_name)
SELECT company_id, 'ROLE_USER', 'User' FROM companies
ON CONFLICT (company_id, role_code) DO NOTHING;

INSERT INTO roles (company_id, role_code, role_name)
SELECT company_id, 'ROLE_VIEWER', 'Viewer' FROM companies
ON CONFLICT (company_id, role_code) DO NOTHING;

INSERT INTO user_roles (user_id, role_id)
SELECT ur.user_id, r_user.role_id
FROM user_roles ur
INNER JOIN roles old_role ON old_role.role_id = ur.role_id
INNER JOIN users u ON u.user_id = ur.user_id
INNER JOIN roles r_user ON r_user.company_id = u.company_id AND r_user.role_code = 'ROLE_USER'
WHERE old_role.role_code IN ('ROLE_MANAGER', 'ROLE_ACCOUNTANT')
ON CONFLICT DO NOTHING;

DELETE FROM role_permissions
WHERE role_id IN (SELECT role_id FROM roles WHERE role_code IN ('ROLE_MANAGER', 'ROLE_ACCOUNTANT'));

DELETE FROM user_roles
WHERE role_id IN (SELECT role_id FROM roles WHERE role_code IN ('ROLE_MANAGER', 'ROLE_ACCOUNTANT'));

DELETE FROM roles
WHERE role_code IN ('ROLE_MANAGER', 'ROLE_ACCOUNTANT');

-- Baseline Viewer: read-only business visibility.
INSERT INTO role_permissions (role_id, permission_id)
SELECT r.role_id, p.permission_id
FROM roles r CROSS JOIN permissions p
WHERE r.role_code = 'ROLE_VIEWER'
  AND p.permission_code IN ('COMPANY_VIEW','USER_VIEW','ROLE_VIEW','PERMISSION_VIEW',
                            'ACCOUNTING_VIEW','INVENTORY_VIEW','SALES_VIEW','PURCHASE_VIEW',
                            'REPORT_VIEW','SYSTEM_VIEW')
  AND p.is_active = TRUE
ON CONFLICT DO NOTHING;

-- Baseline User: business operations, without security/role administration.
INSERT INTO role_permissions (role_id, permission_id)
SELECT r.role_id, p.permission_id
FROM roles r CROSS JOIN permissions p
WHERE r.role_code = 'ROLE_USER'
  AND p.permission_code IN ('COMPANY_VIEW','ACCOUNTING_VIEW','ACCOUNTING_EDIT','JOURNAL_POST',
                            'INVENTORY_VIEW','INVENTORY_EDIT','SALES_VIEW','SALES_EDIT',
                            'PURCHASE_VIEW','PURCHASE_EDIT','REPORT_VIEW')
  AND p.is_active = TRUE
ON CONFLICT DO NOTHING;

-- Administrator remains the only built-in role with full current permissions.
INSERT INTO role_permissions (role_id, permission_id)
SELECT r.role_id, p.permission_id
FROM roles r CROSS JOIN permissions p
WHERE r.role_code = 'ROLE_ADMINISTRATOR' AND r.is_active = TRUE AND p.is_active = TRUE
ON CONFLICT DO NOTHING;
