DELETE FROM role_permissions WHERE role_id IN (SELECT role_id FROM roles WHERE role_code='ROLE_USER');
INSERT INTO role_permissions(role_id,permission_id)
SELECT r.role_id,p.permission_id FROM roles r CROSS JOIN permissions p
WHERE r.role_code='ROLE_USER' AND p.is_active=true AND p.permission_code NOT IN ('ACC.FISCAL.ROLL_FORWARD','COMPANY_CREATE','COMPANY_EDIT','COMPANY_DELETE','USER_VIEW','USER_CREATE','USER_EDIT','USER_DELETE','ROLE_VIEW','ROLE_EDIT','PERMISSION_VIEW','ORG.COMPANY.CREATE','ORG.COMPANY.DELETE','ORG.COMPANY.UPDATE','SYS.ADMIN','SYS.PERMISSIONS.VIEW','SYS.PERMISSIONS.MANAGE','SYS.PERMISSION_TEMPLATES.MANAGE','SYS.ROLES.CREATE','SYS.ROLES.DELETE','SYS.ROLES.UPDATE','SYS.ROLES.VIEW','SYS.USERS.CREATE','SYS.USERS.DELETE','SYS.USERS.DISABLE','SYS.USERS.UPDATE','SYS.USERS.VIEW') ON CONFLICT DO NOTHING;
DELETE FROM role_permissions WHERE role_id IN (SELECT role_id FROM roles WHERE role_code='ROLE_VIEWER');
INSERT INTO role_permissions(role_id,permission_id)
SELECT r.role_id,p.permission_id FROM roles r CROSS JOIN permissions p
WHERE r.role_code='ROLE_VIEWER' AND p.is_active=true AND (p.operation_code='VIEW' OR p.permission_code IN ('SYS.SETTINGS.VIEW','SYS.USERS.VIEW','SYS.ROLES.VIEW','SYS.PERMISSIONS.VIEW','REPORT.VIEW','AUDIT.VIEW','SYSTEM.VIEW')) ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id)
SELECT r.role_id,p.permission_id FROM roles r CROSS JOIN permissions p WHERE r.role_code='ROLE_ADMINISTRATOR' AND p.is_active=true ON CONFLICT DO NOTHING;

-- @shoutech-migration 008_outbound_messages.sql 3E77969CEFAC3864D513D7311673013F6C7419C202C0220207CA6269FA7DFD4C 8C5C0D6DED20073F239C46C72081AA1C397ABC98CE01B9B547122C745BD1A9EE 8C5C0D6DED20073F239C46C72081AA1C397ABC98CE01B9B547122C745BD1A9EE 8C5C0D6DED20073F239C46C72081AA1C397ABC98CE01B9B547122C745BD1A9EE
CREATE TABLE IF NOT EXISTS outbound_messages (
    outbound_message_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    company_id uuid,
    channel varchar(20) NOT NULL CHECK (channel IN ('WEBHOOK', 'EMAIL', 'SMS')),
    recipient_address text NOT NULL,
    subject varchar(500),
    body text NOT NULL,
    body_format varchar(20) NOT NULL DEFAULT 'TEXT',
    status varchar(20) NOT NULL DEFAULT 'QUEUED' CHECK (status IN ('QUEUED', 'SENDING', 'SENT', 'FAILED')),
    attempt_count integer NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
    max_attempts integer NOT NULL DEFAULT 6 CHECK (max_attempts > 0),
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    last_error varchar(1000),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    sent_at timestamptz
);
CREATE INDEX IF NOT EXISTS ix_outbound_messages_due
    ON outbound_messages(status, next_attempt_at, outbound_message_id);
-- @shoutech-migration 013_deletion_audit.sql FE084BC41EE3D18A8026ADC2120DDEE47B2D30E2DC3E5024AD2794CDEA9B3C30 3C715A2063E526892B2DA6093128FE68A5DB8F3B271AE813B654F0B9879FAACF 3C715A2063E526892B2DA6093128FE68A5DB8F3B271AE813B654F0B9879FAACF 3C715A2063E526892B2DA6093128FE68A5DB8F3B271AE813B654F0B9879FAACF
-- Delete audit storage is DBA-owned; service code only records audit events.
CREATE TABLE IF NOT EXISTS deletion_audit_log (
    event_id TEXT PRIMARY KEY,
    company_code TEXT NOT NULL,
    table_name TEXT NOT NULL,
    record_key TEXT NOT NULL,
    action_type TEXT NOT NULL,
    actor TEXT NOT NULL,
    occurred_at TEXT NOT NULL,
    method TEXT NOT NULL,
    reason TEXT,
    record_snapshot TEXT
);
CREATE INDEX IF NOT EXISTS ix_deletion_audit_company_time
    ON deletion_audit_log(company_code, occurred_at);
