INSERT INTO role_permissions (role_id, permission_id)
SELECT r.role_id, p.permission_id FROM roles r CROSS JOIN permissions p
WHERE r.role_code = 'ROLE_ADMINISTRATOR' AND r.is_active = true AND p.is_active = true AND p.permission_code IN ('ACC.CREATE','ACC.DELETE','ACC.POST','ACC.VIEW','INV.CREATE','INV.DELETE','INV.MOVE','INV.VIEW','PURCH.CREATE','PURCH.ORDER.CONVERT','PURCH.POST','PURCH.VIEW','SALES.CREATE','SALES.ORDER.CONVERT','SALES.POST','SALES.VIEW','SYS.BACKUP','SYS.CUSTOM_FIELDS.MANAGE','SYS.SETTINGS','SYS.USERS') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions (role_id, permission_id)
SELECT r.role_id, p.permission_id FROM roles r CROSS JOIN permissions p
WHERE r.role_code = 'ROLE_USER' AND r.is_active = true AND p.is_active = true AND p.permission_code IN ('ACC.CREATE','ACC.POST','ACC.VIEW','INV.CREATE','INV.MOVE','INV.VIEW','PURCH.CREATE','PURCH.ORDER.CONVERT','PURCH.POST','PURCH.VIEW','SALES.CREATE','SALES.ORDER.CONVERT','SALES.POST','SALES.VIEW','SYS.BACKUP','SYS.CUSTOM_FIELDS.MANAGE','SYS.SETTINGS','SYS.USERS') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions (role_id, permission_id)
SELECT r.role_id, p.permission_id FROM roles r CROSS JOIN permissions p
WHERE r.role_code = 'ROLE_VIEWER' AND r.is_active = true AND p.is_active = true AND p.permission_code IN ('ACC.VIEW','INV.VIEW','PURCH.VIEW','SALES.VIEW') ON CONFLICT DO NOTHING;
