-- 115 - Report Designer completion (PostgreSQL, services phase B2).
-- See the SQLite companion for the design note: the CustomReport*
-- store was never created by any earlier migration; this migration
-- creates it (IF NOT EXISTS) and adds the B2 styling / page-setup
-- columns plus CustomReportColumns.TotalsFormula. Flag columns are
-- INTEGER (0/1) because ReportRepo's shared SQL filters
-- IsDeleted = 0 on both providers.

CREATE TABLE IF NOT EXISTS CustomReportDefinitions (
    ReportDefID INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    CompanyID TEXT NOT NULL,
    ReportKey TEXT NOT NULL,
    ReportName TEXT NOT NULL,
    Description TEXT,
    LanguageCode TEXT NOT NULL DEFAULT 'ar',
    OwnerUserID INTEGER NOT NULL DEFAULT 0,
    Visibility TEXT NOT NULL DEFAULT 'PRIVATE',
    DataSourceKey TEXT NOT NULL DEFAULT '',
    PageOrientation TEXT NOT NULL DEFAULT 'PORTRAIT',
    ShowTotalsRow INTEGER NOT NULL DEFAULT 1,
    ShowHeaderInfo INTEGER NOT NULL DEFAULT 1,
    FreezeFirstColumn INTEGER NOT NULL DEFAULT 0,
    IsFavorite INTEGER NOT NULL DEFAULT 0,
    IsSystem INTEGER NOT NULL DEFAULT 0,
    IsDeleted INTEGER NOT NULL DEFAULT 0,
    TitleFontFamily TEXT,
    TitleFontSize DOUBLE PRECISION NOT NULL DEFAULT 20,
    TitleBold INTEGER NOT NULL DEFAULT 1,
    HeaderFontFamily TEXT,
    HeaderFontSize DOUBLE PRECISION NOT NULL DEFAULT 10.5,
    HeaderBold INTEGER NOT NULL DEFAULT 1,
    HeaderBackColor TEXT,
    HeaderTextColor TEXT,
    BodyFontFamily TEXT,
    BodyFontSize DOUBLE PRECISION NOT NULL DEFAULT 10,
    TotalsFontFamily TEXT,
    TotalsFontSize DOUBLE PRECISION NOT NULL DEFAULT 10,
    TotalsBold INTEGER NOT NULL DEFAULT 1,
    BandingColor TEXT,
    ShowGridLines INTEGER NOT NULL DEFAULT 1,
    PageSize TEXT NOT NULL DEFAULT 'A4',
    MarginMm DOUBLE PRECISION NOT NULL DEFAULT 12,
    ShowCompanyAddress INTEGER NOT NULL DEFAULT 0,
    CreatedBy TEXT,
    UpdatedBy TEXT,
    CreatedAt TIMESTAMP NOT NULL DEFAULT NOW(),
    UpdatedAt TIMESTAMP,
    DeletedAt TIMESTAMP,
    DeletedBy TEXT
);

CREATE TABLE IF NOT EXISTS CustomReportColumns (
    ReportColID INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    CompanyID TEXT NOT NULL,
    ReportDefID INTEGER NOT NULL,
    FieldKey TEXT NOT NULL,
    CaptionAR TEXT NOT NULL DEFAULT '',
    CaptionEN TEXT,
    DisplayOrder INTEGER NOT NULL DEFAULT 0,
    ColumnWidth NUMERIC(10,2) NOT NULL DEFAULT 120,
    IsVisible INTEGER NOT NULL DEFAULT 1,
    IsLocked INTEGER NOT NULL DEFAULT 0,
    ColumnType TEXT NOT NULL DEFAULT 'DATA',
    FormulaText TEXT,
    TotalsFormula TEXT,
    DataFormat TEXT NOT NULL DEFAULT 'TEXT',
    DecimalPlaces INTEGER NOT NULL DEFAULT 2,
    AggregateFunc TEXT,
    NegativeInRed INTEGER NOT NULL DEFAULT 1,
    IsDeleted INTEGER NOT NULL DEFAULT 0,
    CreatedBy TEXT,
    DeletedAt TIMESTAMP,
    DeletedBy TEXT
);

CREATE TABLE IF NOT EXISTS CustomReportGroupings (
    ReportGrpID INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    CompanyID TEXT NOT NULL,
    ReportDefID INTEGER NOT NULL,
    FieldKey TEXT NOT NULL,
    GroupLevel INTEGER NOT NULL DEFAULT 0,
    ShowSubTotals INTEGER NOT NULL DEFAULT 1,
    StartOnNewPage INTEGER NOT NULL DEFAULT 0,
    SortDirection TEXT NOT NULL DEFAULT 'ASC',
    IsDeleted INTEGER NOT NULL DEFAULT 0,
    CreatedBy TEXT,
    DeletedAt TIMESTAMP,
    DeletedBy TEXT
);

CREATE TABLE IF NOT EXISTS CustomReportFilters (
    ReportFilterID INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    CompanyID TEXT NOT NULL,
    ReportDefID INTEGER NOT NULL,
    FilterKey TEXT NOT NULL,
    FilterLabelAR TEXT NOT NULL DEFAULT '',
    Operator TEXT NOT NULL DEFAULT 'EQ',
    ValueFrom TEXT,
    ValueTo TEXT,
    IsPrompted INTEGER NOT NULL DEFAULT 0,
    IsRequired INTEGER NOT NULL DEFAULT 0,
    IsDeleted INTEGER NOT NULL DEFAULT 0,
    CreatedBy TEXT,
    DeletedAt TIMESTAMP,
    DeletedBy TEXT
);

